55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	} as const satisfies Record<string, number>;
67	
68	type InsurableItemType = keyof typeof BASE_PREMIUMS;
69	
70	const isInsurableItemType = (type: string): type is InsurableItemType =>
71	  type in BASE_PREMIUMS;
72	
73	// Unknown item types are not yet rejected — the spec requires an error, but no
74	// test drives that behaviour yet, so they are priced at 0 for the moment.
75	const UNPRICED_UNKNOWN_TYPE = 0;
76	
77	const basePremiumForItem = (item: Item): number =>
78	  isInsurableItemType(item.type)
79	    ? BASE_PREMIUMS[item.type]
80	    : UNPRICED_UNKNOWN_TYPE;
81	
82	const BLOCK_SIZE = 3;
83	
84	const BLOCK_BASE_PREMIUM = 60;
85	
86	const areAllSameType = (items: Item[]): boolean =>
87	  items.every((item) => item.type === items[0]?.type);
88	
89	// A block is not carved out of a larger group: the block price applies only
90	// when the group consists of exactly three alike components (7 runes cost
91	// 7 × 25, not 60 + 60 + 25). The rule is currently evaluated over the whole
92	// item list — grouping by type comes with the pending
93	// 3-runes-plus-3-moonstones test.
94	const qualifiesForBlockPrice = (items: Item[]): boolean =>
95	  items.length === BLOCK_SIZE && areAllSameType(items);
96	
97	const sumBasePremiums = (items: Item[]): number =>
98	  items.reduce((sum, item) => sum + basePremiumForItem(item), 0);
99	
100	const basePremiumForItems = (items: Item[]): number =>
101	  qualifiesForBlockPrice(items) ? BLOCK_BASE_PREMIUM : sumBasePremiums(items);
102	
103	const withInitialAssessmentSurcharge = (basePremium: number): number =>
104	  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
105	
106	const quotePremium = (items: Item[]): number =>
107	  Math.round(
108	    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
109	  );
110	
111	const runStep = (step: Step): StepResult => {
112	  if (step.op === "quote") return { premium: quotePremium(step.items) };
113	  throw new Error(`Unsupported step: ${step.op}`);
114	};
115	
116	export const runScenario = (scenario: Scenario): ScenarioResult => ({
117	  results: scenario.steps.map(runStep),
118	});
